// Batch installer for 10-tier weapon icon sheets generated by image-generator.
// Usage: node .agents/skills/tales-tales-pixel-art/scripts/install-weapon-sheets.mjs <sheets-map.json> [contact-out.png]
// sheets-map.json supports:
//   - string path (3x2 grid = T1..T6), OR
//   - { "t1_6": "path/to/3x2.jpg", "t7_10": "path/to/2x2.jpg" } (T1..T6 from 3x2, T7..T10 from 2x2)
// Extracts crisp 32x32 transparent PNGs to game/public/assets/weapons/<kind>/<kind>_t<tier>.png,
// registers `icon.weapon.<kind>.t<tier>` in game/public/assets/manifest.json, and renders a 4x contact sheet.

import fs from "fs";
import path from "path";
import zlib from "zlib";
import crypto from "crypto";
import { execFileSync } from "child_process";
import { installCanvas } from "../../../game/scripts/pixcanvas.mjs";

installCanvas();

const KINDS = ["sword", "dagger", "spear", "hammer", "staff", "book", "bow"];

function encodePng(w, h, rgba) {
  const crcTable = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    crcTable[n] = c >>> 0;
  }
  const crc32 = (buf) => {
    let c = 0xffffffff;
    for (let i = 0; i < buf.length; i++) c = crcTable[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
    return (c ^ 0xffffffff) >>> 0;
  };
  const chunk = (type, data) => {
    const t = Buffer.from(type), len = Buffer.alloc(4);
    len.writeUInt32BE(data.length, 0);
    const c = Buffer.alloc(4);
    c.writeUInt32BE(crc32(Buffer.concat([t, data])), 0);
    return Buffer.concat([len, t, data, c]);
  };
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0);
  ihdr.writeUInt32BE(h, 4);
  ihdr[8] = 8;
  ihdr[9] = 6;
  const raw = Buffer.alloc((w * 4 + 1) * h);
  for (let y = 0; y < h; y++) {
    raw[y * (w * 4 + 1)] = 0;
    Buffer.from(rgba.buffer, rgba.byteOffset + y * w * 4, w * 4).copy(raw, y * (w * 4 + 1) + 1);
  }
  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk("IHDR", ihdr),
    chunk("IDAT", zlib.deflateSync(raw)),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}

function decodeImageWindows(imgPath, tmpBin) {
  const ps = [
    "Add-Type -AssemblyName System.Drawing;",
    `$bmp = New-Object System.Drawing.Bitmap('${imgPath.replace(/'/g, "''")}');`,
    "$w = $bmp.Width; $h = $bmp.Height;",
    "$rect = New-Object System.Drawing.Rectangle(0, 0, $w, $h);",
    "$bd = $bmp.LockBits($rect, [System.Drawing.Imaging.ImageLockMode]::ReadOnly, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb);",
    "$bytes = New-Object byte[] ($w * $h * 4);",
    "[System.Runtime.InteropServices.Marshal]::Copy($bd.Scan0, $bytes, 0, $bytes.Length);",
    "$bmp.UnlockBits($bd); $bmp.Dispose();",
    `[System.IO.File]::WriteAllBytes('${tmpBin.replace(/'/g, "''")}', $bytes);`,
    'Write-Output "$w,$h"',
  ].join(" ");
  const out = execFileSync("powershell", ["-NoProfile", "-Command", ps], { encoding: "utf8" }).trim();
  const [w, h] = out.split(",").map(Number);
  const bgra = fs.readFileSync(tmpBin);
  try { fs.unlinkSync(tmpBin); } catch {}
  return { w, h, bgra };
}

function isMagenta(r, g, b) {
  return r > 145 && b > 135 && g < 115 && (r - g) > 65 && (b - g) > 60;
}

function extractIcon(bgra, W0, H0, col, row, cols, rows, { thinStroke = false } = {}) {
  const x0 = Math.floor((col * W0) / cols), x1 = Math.floor(((col + 1) * W0) / cols);
  const y0 = Math.floor((row * H0) / rows), y1 = Math.floor(((row + 1) * H0) / rows);
  const cw = x1 - x0, ch = y1 - y0;
  const mask = new Uint8Array(cw * ch);
  const q = new Int32Array(cw * ch);
  let head = 0, tail = 0;

  const tryPush = (x, y) => {
    if (x < 0 || y < 0 || x >= cw || y >= ch) return;
    const idx = y * cw + x;
    if (mask[idx]) return;
    const gi = ((y0 + y) * W0 + (x0 + x)) * 4;
    const b = bgra[gi], g = bgra[gi + 1], r = bgra[gi + 2];
    if (isMagenta(r, g, b)) { mask[idx] = 1; q[tail++] = idx; }
  };

  for (let x = 0; x < cw; x++) { tryPush(x, 0); tryPush(x, ch - 1); }
  for (let y = 0; y < ch; y++) { tryPush(0, y); tryPush(cw - 1, y); }
  for (let y = 0; y < ch; y++) for (let x = 0; x < cw; x++) {
    const gi = ((y0 + y) * W0 + (x0 + x)) * 4;
    const b = bgra[gi], g = bgra[gi + 1], r = bgra[gi + 2];
    if (r > 210 && b > 205 && g < 60) {
      const idx = y * cw + x;
      if (!mask[idx]) { mask[idx] = 1; q[tail++] = idx; }
    }
  }
  while (head < tail) {
    const idx = q[head++], x = idx % cw, y = (idx / cw) | 0;
    tryPush(x - 1, y); tryPush(x + 1, y); tryPush(x, y - 1); tryPush(x, y + 1);
  }

  let minX = cw, minY = ch, maxX = -1, maxY = -1;
  for (let y = 0; y < ch; y++) for (let x = 0; x < cw; x++) {
    if (!mask[y * cw + x]) {
      if (x < minX) minX = x; if (x > maxX) maxX = x;
      if (y < minY) minY = y; if (y > maxY) maxY = y;
    }
  }
  const bw = maxX - minX + 1, bh = maxY - minY + 1;
  const out = document.createElement("canvas");
  out.width = out.height = 32;
  const ctx = out.getContext("2d");
  const maxSpan = 28;
  const scale = maxSpan / Math.max(bw, bh);
  const tw = Math.max(1, Math.round(bw * scale));
  const th = Math.max(1, Math.round(bh * scale));
  const ox = Math.floor((32 - tw) / 2);
  const oy = Math.floor((32 - th) / 2);

  for (let dy = 0; dy < th; dy++) {
    const sy0 = minY + Math.floor((dy * bh) / th);
    const sy1 = Math.max(sy0 + 1, minY + Math.floor(((dy + 1) * bh) / th));
    for (let dx = 0; dx < tw; dx++) {
      const sx0 = minX + Math.floor((dx * bw) / tw);
      const sx1 = Math.max(sx0 + 1, minX + Math.floor(((dx + 1) * bw) / tw));
      let fgCount = 0, total = 0;
      const samples = [];
      for (let sy = sy0; sy < sy1; sy++) {
        for (let sx = sx0; sx < sx1; sx++) {
          total++;
          if (mask[sy * cw + sx]) continue;
          const gi = ((y0 + sy) * W0 + (x0 + sx)) * 4;
          const b = bgra[gi], g = bgra[gi + 1], r = bgra[gi + 2];
          if (r > g + 40 && b > g + 40 && r > 120 && b > 120 && g < 85 && Math.abs(r - b) < 50) continue;
          fgCount++;
          samples.push([r, g, b, 0.2126 * r + 0.7152 * g + 0.0722 * b]);
        }
      }
      const thresh = thinStroke ? 0.22 : 0.30;
      if (fgCount < total * thresh || samples.length === 0) continue;
      samples.sort((a, b) => a[3] - b[3]);
      const darkCut = thinStroke ? 0.58 : 0.40;
      const darkCount = samples.filter((s) => s[3] < 45).length;
      const pick = darkCount >= samples.length * darkCut
        ? samples[Math.floor(darkCount * 0.5)]
        : samples[Math.floor(samples.length * 0.58)];
      ctx.fillStyle = `rgb(${pick[0]},${pick[1]},${pick[2]})`;
      ctx.fillRect(ox + dx, oy + dy, 1, 1);
    }
  }
  return out;
}

const mapFile = process.argv[2];
if (!mapFile) {
  console.error("Usage: node install-weapon-sheets.mjs <sheets-map.json> [contact-out.png]");
  process.exit(1);
}
const sheetMap = JSON.parse(fs.readFileSync(mapFile, "utf8"));
const contactOut = process.argv[3] || "";
const manifestPath = "game/public/assets/manifest.json";
const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));

const activeKinds = KINDS.filter((k) => sheetMap[k]);
const hasT10 = activeKinds.some((k) => typeof sheetMap[k] === "object" && sheetMap[k].t7_10);
const maxTier = hasT10 ? 10 : 6;
const Z = 3, cell = 32 * Z, pad = 10;
const W = pad + maxTier * (cell + pad), H = pad + activeKinds.length * (cell + pad);
const contact = document.createElement("canvas");
contact.width = W;
contact.height = H;
const cg = contact.getContext("2d");
cg.fillStyle = "#241e2e";
cg.fillRect(0, 0, W, H);

let installed = 0, totalBytes = 0;

function saveTier(kind, r, tier, ic, outDir) {
  const png = encodePng(32, 32, ic._data);
  totalBytes += png.length;
  const fname = `${kind}_t${tier}.png`;
  fs.writeFileSync(path.join(outDir, fname), png);
  const hash = crypto.createHash("sha1").update(png).digest("hex").slice(0, 8);
  manifest.images[`icon.weapon.${kind}.t${tier}`] = { src: `assets/weapons/${kind}/${fname}?v=${hash}`, w: 32, h: 32 };
  installed++;

  const x = pad + (tier - 1) * (cell + pad), y = pad + r * (cell + pad);
  cg.fillStyle = "#362d42"; cg.fillRect(x, y, cell, cell);
  cg.fillStyle = tier >= 7 ? "#d9a742" : "#4e425e"; cg.fillRect(x, y, cell, 2); cg.fillRect(x, y, 2, cell);
  cg.drawImage(ic, 0, 0, 32, 32, x, y, cell, cell);
}

for (let r = 0; r < activeKinds.length; r++) {
  const kind = activeKinds[r];
  const entry = sheetMap[kind];
  const p1_6 = typeof entry === "string" ? entry : entry.t1_6;
  const p7_10 = typeof entry === "object" ? entry.t7_10 : null;
  const outDir = path.join("game/public/assets/weapons", kind);
  fs.mkdirSync(outDir, { recursive: true });
  const thinStroke = kind === "bow" || kind === "spear";

  if (p1_6) {
    const tmpBin = path.join(path.dirname(mapFile), `_tmp_${kind}_1_6.bgra`);
    const { w: W0, h: H0, bgra } = decodeImageWindows(p1_6, tmpBin);
    for (let tier = 1; tier <= 6; tier++) {
      const col = (tier - 1) % 3, row = Math.floor((tier - 1) / 3);
      saveTier(kind, r, tier, extractIcon(bgra, W0, H0, col, row, 3, 2, { thinStroke }), outDir);
    }
  }
  if (p7_10) {
    const tmpBin = path.join(path.dirname(mapFile), `_tmp_${kind}_7_10.bgra`);
    const { w: W0, h: H0, bgra } = decodeImageWindows(p7_10, tmpBin);
    for (let i = 0; i < 4; i++) {
      const col = i % 2, row = Math.floor(i / 2);
      saveTier(kind, r, 7 + i, extractIcon(bgra, W0, H0, col, row, 2, 2, { thinStroke }), outDir);
    }
  }
}

fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + "\n");
if (contactOut) fs.writeFileSync(contactOut, encodePng(W, H, contact._data));
console.log(`Installed ${installed} weapon icons (${(totalBytes / 1024).toFixed(1)} KB).`);
